{
  "title": "Range Between Fact",
  "description": "Create a Fact that enforces a relational constraint between two fields of a struct, such as ensuring that a start field is less than or equal to an end field. The fact accepts getter closures for the fields and a comparison function, making it reusable for different structs.",
  "code_context": "use contrafact::{lambda, Lambda, Target};

pub fn range_between<O, T, FStart, FEnd, C>(label: impl ToString, start: FStart, end: FEnd, cmp: C) -> Lambda<'static, O, O>
where
    O: Target<'static> + Clone,
    T: Target<'static> + PartialOrd + Clone,
    FStart: Fn(&O) -> T + Clone + Send + Sync,
    FEnd: Fn(&O) -> T + Clone + Send + Sync,
    C: Fn(&T, &T) -> bool + Clone + Send + Sync,
{
    lambda("range_between", (), move |g, (), mut o: O| {
        let s = start(&o);
        let e = end(&o);
        if !cmp(&s, &e) {
            g.fail(format!("range constraint failed: start {:?} end {:?}", s, e))?;
        }
        Ok(o)
    })
}",
